{
  "findings": [
    {
      "ref": "[D520]",
      "area": "contact",
      "claim": "A parent reports that direct messages and party chats can be disabled with parental controls.",
      "stance": "mitigation",
      "quote": "Direct messages and party chats can be disabled with parental controls."
    },
    {
      "ref": "[D520]",
      "area": "contact",
      "claim": "A parent reports that some chats built into mini-games cannot be disabled.",
      "stance": "risk",
      "quote": "Chats built into the coding of specific mini-games cannot be disabled, and kids can type text on \"signs\" regardless of communication preferences."
    },
    {
      "ref": "[D520]",
      "area": "money",
      "claim": "A parent reports that Roblox uses Robux, a digital currency, for in-game purchases.",
      "stance": "neutral",
      "quote": "Key elements of the games include ads, official product placements, and the need for Robux, the platform's digital currency, to access gated extras."
    },
    {
      "ref": "[D520]",
      "area": "data",
      "claim": "A parent reports that Roblox may process age verification images through third-party providers without a guaranteed retention period.",
      "stance": "risk",
      "quote": "Images used for age verification may be processed by third-party providers, but Roblox does not publicly guarantee a fixed retention period for the images of children."
    },
    {
      "ref": "[D520]",
      "area": "age_gating",
      "claim": "A parent reports that the age verification system can make mistakes, potentially loosening protections for younger users.",
      "stance": "risk",
      "quote": "Roblox uses this information to estimate or verify a user’s age and place accounts into age-based categories. Under Roblox’s newer system, users age 5 to 8 may be placed into \"Roblox Kids\" accounts, while users age 9 to 15 may be placed into \"Roblox Select\" accounts. However, the system can make mistakes."
    },
    {
      "ref": "[D520]",
      "area": "content",
      "claim": "A parent reports that extreme violence, inappropriate language, and sexually explicit content can be found in user-created games.",
      "stance": "risk",
      "quote": "Extreme violence, inappropriate language, and sexually explicit content is possible (and quite likely) within the user-created games."
    },
    {
      "ref": "[D520]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory scrutiny over age verification and data handling.",
      "stance": "risk",
      "quote": "Roblox uses AI-based age estimation and verification systems for some users. Users over age 13 may be asked to submit a live selfie or upload a government ID to access certain communication features."
    }
  ]
}
